import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  // In production, this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    next();
  } catch (e) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', extractTenant, async (req, res) => {
  try {
    const { category, tag, sort_by, order } = req.query;

    // Base query with tenant isolation
    let query = `SELECT a.id, a.name, a.category, a.metadata, a.created_at 
                 FROM assets a 
                 WHERE a.tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    // Category filter - parameterized
    if (category) {
      query += ` AND a.category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    // Tag filter - parameterized  
    if (tag) {
      query += ` AND a.tags @> ARRAY[$${paramIdx}]::text[]`;
      params.push(tag);
      paramIdx++;
    }

    // Dynamic sort - VULNERABLE: sort_by is interpolated directly
    const allowedOrders = ['ASC', 'DESC'];
    const sanitizedOrder = allowedOrders.includes(order?.toUpperCase()) ? order.toUpperCase() : 'DESC';

    if (sort_by) {
      // Developer assumed sort_by would be a simple column name
      // but it's directly interpolated into the query
      query += ` ORDER BY ${sort_by} ${sanitizedOrder}`;
    } else {
      query += ` ORDER BY a.created_at DESC`;
    }

    query += ` LIMIT 100`;

    const result = await pool.query(query, params);

    // Log access for audit
    const auditHash = crypto.createHash('sha256')
      .update(`${req.userId}:${req.tenantId}:${Date.now()}`)
      .digest('hex').slice(0, 16);
    console.log(`[AUDIT:${auditHash}] search tenant=${req.tenantId} category=${category} tag=${tag} sort=${sort_by}`);

    res.json({
      results: result.rows,
      count: result.rows.length,
      trace_id: auditHash
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal search error' });
  }
});

// Bulk export endpoint
app.post('/api/v2/assets/export', extractTenant, async (req, res) => {
  const { asset_ids, format } = req.body;
  if (!Array.isArray(asset_ids) || asset_ids.length > 500) {
    return res.status(400).json({ error: 'Invalid asset_ids' });
  }

  const placeholders = asset_ids.map((_, i) => `$${i + 2}`).join(',');
  const query = `SELECT * FROM assets WHERE tenant_id = $1 AND id IN (${placeholders})`;
  const result = await pool.query(query, [req.tenantId, ...asset_ids]);

  res.json({ exported: result.rows.length, format: format || 'json' });
});

app.listen(process.env.PORT || 3000);
